('bmlt-cytogenetics-karyotyping-fish-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',3600,$json${"question":"The normal human diploid chromosome number is:","translation":"","options":["23","46","44","48"],"correctIndex":1,"explanation":"Most human somatic cells contain 46 chromosomes arranged in 23 pairs.","explanationNe":"सामान्य मानव somatic cell मा २३ जोडी अर्थात् ४६ chromosome हुन्छन्।","topic":"Chromosome number"}$json$::jsonb,true),
